import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.Executors;

// Imita a TransLog. Controle: GET /control?status=200&body=...&delay=0
public class Stub {
    static volatile int status = 200;
    static volatile String body = "{\"price_cents\":3310,\"eta_hours\":41}";
    static volatile long delay = 0;

    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9099), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/control", ex -> {
            Map<String, String> q = parse(ex.getRequestURI().getRawQuery());
            if (q.containsKey("status")) status = Integer.parseInt(q.get("status"));
            if (q.containsKey("body")) body = q.get("body");
            if (q.containsKey("delay")) delay = Long.parseLong(q.get("delay"));
            byte[] r = ("ok " + status + " " + delay + " " + body).getBytes();
            ex.sendResponseHeaders(200, r.length);
            ex.getResponseBody().write(r);
            ex.close();
        });
        s.createContext("/", ex -> {
            System.out.println("REQ " + ex.getRequestURI());
            System.out.flush();
            try { Thread.sleep(delay); } catch (InterruptedException e) {}
            byte[] r = body.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(status, r.length == 0 ? -1 : r.length);
            if (r.length > 0) ex.getResponseBody().write(r);
            ex.close();
        });
        s.start();
        System.out.println("stub up");
    }

    static Map<String, String> parse(String q) {
        Map<String, String> m = new HashMap<>();
        if (q == null) return m;
        for (String p : q.split("&")) {
            int i = p.indexOf('=');
            m.put(URLDecoder.decode(p.substring(0, i), StandardCharsets.UTF_8),
                  URLDecoder.decode(p.substring(i + 1), StandardCharsets.UTF_8));
        }
        return m;
    }
}

