sku desconhecido + tier invalido => 422 {"error":"UNKNOWN_PRODUCT"} | order: 422 {"error":"UNKNOWN_PRODUCT"}
fora de linha + sem estoque (BON,REL) => 422 {"error":"INSUFFICIENT_STOCK"} | order: 422 {"error":"INSUFFICIENT_STOCK"}
fora de linha + sem estoque (REL,BON) => 422 {"error":"INSUFFICIENT_STOCK"} | order: 422 {"error":"INSUFFICIENT_STOCK"}
sem estoque + tier invalido => 422 {"error":"INSUFFICIENT_STOCK"} | order: 422 {"error":"INSUFFICIENT_STOCK"}
tier + regiao invalidos => 422 {"error":"INVALID_CLUB_TIER"} | order: 422 {"error":"INVALID_CLUB_TIER"}
regiao + cep invalidos => 422 {"error":"INVALID_REGION"} | order: 422 {"error":"INVALID_REGION"}
cep + entrega invalidos => 422 {"error":"INVALID_ZIP_CODE"} | order: 422 {"error":"INVALID_ZIP_CODE"}
motoboy>5kg + cupom invalido => 422 {"error":"SHIPPING_METHOD_UNAVAILABLE"} | order: 422 {"error":"SHIPPING_METHOD_UNAVAILABLE"}
cupom invalido + pagto invalido => 422 {"error":"INVALID_COUPON"} | order: 422 {"error":"INVALID_COUPON"}
cupom nao aplicavel + pagto invalido => 422 {"error":"COUPON_NOT_APPLICABLE"} | order: 422 {"error":"COUPON_NOT_APPLICABLE"}
pagto invalido + parcelas => 422 {"error":"INVALID_PAYMENT_METHOD"} | order: 422 {"error":"INVALID_PAYMENT_METHOD"}
parcelas + boleto >1000 => 422 {"error":"INVALID_INSTALLMENTS"} | order: 422 {"error":"INVALID_INSTALLMENTS"}

